        header{background:#0066cc;color:#fff;padding:10px 0;}
        header .logo{font-size:24px;font-weight:bold;margin-left:20px;}
        nav{margin-top:10px;}
        nav a{color:#fff;margin:0 15px;text-decoration:none;font-size:16px;}
        nav a:hover{text-decoration:underline;}
        .search-box{background:#fff;padding:30px;margin-top:30px;border-radius:8px;box-shadow:0 2px 5px rgba(0,0,0,0.1);}
        .search-box h2{margin-top:0;}
        .form-group{margin-bottom:15px;}
        .form-group label{display:block;margin-bottom:5px;font-weight:bold;}
        .form-group input{width:100%;padding:8px;border:1px solid #ccc;border-radius:4px;}
        .form-group input[type="date"]{padding-right:0;}
        .btn{background:#0066cc;color:#fff;padding:10px 20px;border:none;border-radius:4px;cursor:pointer;font-size:16px;}
        .btn:hover{background:#004a99;}
        footer{background:#333;color:#fff;padding:20px;text-align:center;margin-top:40px;}
        @media (max-width:768px){
            header .logo,nav{text-align:center;}
            nav a{display:block;margin:10px 0;}
        }
    </style>
</head>
<body>
    <header>
        <div class="container">
            <div class="logo">畅行旅行</div>
            <nav>
                <a href="index.html">首页</a>
                <a href="about.html">关于我们</a>
                <a href="contact.html">联系我们</a>
            </nav>
        </div>
    </header>

    <main class="container">
        <section class="search-box">
            <h2>寻找您的下一段旅程</h2>
            <form id="searchForm">
                <div class="form-group">
                    <label for="destination">目的地</label>
                    <input type="text" id="destination" name="destination" placeholder="如：北京、上海、丽江" required>
                </div>
                <div class="form-group">
                    <label for="checkin">入住日期</label>
                    <input type="date" id="checkin" name="checkin" required>
                </div>
                <div class="form-group">
                    <label for="checkout">退房日期</label>
                    <input type="date" id="checkout" name="checkout" required>
                </div>
                <button type="submit" class="btn">搜索酒店</button>
            </form>
        </section>
    </main>

    <footer>
        © 2026 畅行旅行. 保留所有权利.
    </footer>

    <script>
        document.getElementById('searchForm').addEventListener('submit', function(e){
            e.preventDefault();
            const dest = encodeURIComponent(document.getElementById('destination').value.trim());
            const inDate = document.getElementById('checkin').value;
            const outDate = document.getElementById('checkout').value;
            if(inDate && outDate && dest){
                const query = `?dest=${dest}&in=${inDate}&out=${outDate}`;
                window.location.href = 'results.html' + query;
            }
        });
    </script>
</body>
</html>

